"""Daily work and project entry points using real, paginated server data."""

WORKSPACE_JS = r"""
const WS={view:'',q:'',stage:'all',handoffState:'all',offset:0,read:0,lastScope:null,page:null,selected:''};
const WS_STAGES={requirement:'需求',development:'研发',testing:'测试',delivery:'交付',operations:'运维',unrecorded:'未登记阶段'};
function wsRefresh(){return vWorkspace()}
function wsProject(key,route){setProj(key);S.scope=key;ls.set('tmh.scope',key);location.hash=route||'#/projects/'+encodeURIComponent(key)}
function wsWaiting(seconds){if(seconds===null||seconds===undefined)return '等待时长未知';const n=Math.max(0,Number(seconds));if(!Number.isFinite(n))return '等待时长未知';return n<60?'等待不足 1 分钟':n<3600?'等待 '+Math.floor(n/60)+' 分钟':n<86400?'等待 '+Math.floor(n/3600)+' 小时 '+Math.floor(n%3600/60)+' 分钟':'等待 '+Math.floor(n/86400)+' 天 '+Math.floor(n%86400/3600)+' 小时'}
function wsHandoffWait(record,seconds){return !record?'等待时长未知':['waiting','blocked'].includes(record.status)?wsWaiting(seconds):'当前不在等待'}
function wsActionHref(t,review=false){return t.action_href||((review||t.work?.needs_review)?'#/team/ticket/':'#/t/')+encodeURIComponent(t.key)}
function wsMeetingLink(t){const a=t.meeting_action;return a?`<p class="ws-row-meta"><a data-ws-meeting="${h(a.meeting_id)}" data-ws-project="${h(t.project)}" href="#/meetings/${encodeURIComponent(a.meeting_id)}/${encodeURIComponent(t.project)}">会议行动：${h(a.meeting_title||a.title||'查看会议来源')}</a> · 期限 ${h(a.due_date||'未约定')}</p>`:''}
function wsTaskRow(t,review=false){return `<article class="ws-row"><span class="ws-task-marker state-${h(t.status)}" aria-hidden="true"></span><div class="grow"><a class="ws-row-title" href="#/t/${encodeURIComponent(t.key)}">${h(t.title)}</a><div class="ws-row-meta">${h(t.key)} · 负责人 ${h(t.assignee||'待分配')} ${t.reviewer?'· 复核 '+h(t.reviewer):''}</div><div class="ws-row-meta">${h(t.work?.label||'打开任务查看进展')}</div></div>${wsMeetingLink(t)}${stPill(t.status)}<a class="btn ghost" href="${h(wsActionHref(t,review))}">${h(t.action_label||'查看任务')}</a></article>`}
function wsLive(page){return WS.page===page&&page.host.isConnected&&page.route===location.hash&&page.scope===scopeQ()}
function wsShell(){
 const host=$('#main');host.innerHTML=`<div id="workspacePage"><div class="ws-head"><div><div class="ws-eyebrow" id="wsScope"></div><h1>工作台</h1><p>从当前责任人、交接材料和下一步继续。</p></div><div class="wk-toolbar"><a class="btn" href="#/meetings">会议与行动</a><button id="wsReload">刷新队列</button><button class="primary" onclick="newTicket()">新建任务</button></div></div><div class="ws-queue-tabs" id="wsViews" role="group" aria-label="工作范围"></div><div class="ws-stage-strip" id="wsStages" role="group" aria-label="交接阶段筛选"></div><div class="ws-filterbar"><form class="ws-search" id="wsSearchForm"><label for="wsSearch">查找任务</label><input type="search" id="wsSearch" placeholder="任务名称、正文、编号或责任人" value="${h(WS.q)}"><button>搜索</button></form><label class="ws-filter-label" for="wsHandoffState">交接状态<select id="wsHandoffState"><option value="all">全部状态</option><option value="waiting">待接收</option><option value="received">已接收</option><option value="returned">已退回</option><option value="blocked">已阻塞</option><option value="withdrawn">已撤回</option><option value="none">尚无交接</option></select></label></div><p class="sub ws-boundary">我的 / 团队是工作视图，不是项目权限隔离。交接阶段由明确登记产生，历史未登记显示未知。</p><div id="wsQueueNotice" role="status" aria-live="polite"></div><div class="ws-flow-layout"><section aria-label="任务队列"><div class="ws-list" id="wsQueue"></div><div class="ws-pagination"><span class="sub" id="wsPageCount"></span><button id="wsPrev">上一页</button><button id="wsNext">下一页</button></div><div class="ws-work-links"><a href="#/team/unassigned">分配任务</a><a href="#/projects">项目与资产</a><a href="#/memory/clusters">知识与经验</a><a href="#/deliveries">交付记录</a></div></section><aside id="wsDetail" class="ws-detail" aria-label="任务和交接详情"><div class="ws-empty"><h2>选择一项任务</h2><p>在同一处查看完整需求、固定依据、责任人和交接记录。</p></div></aside></div></div>`;
 const page={host:$('#workspacePage'),route:location.hash,scope:scopeQ(),selection:0};WS.page=page;
 $('#wsHandoffState').value=WS.handoffState;
 $('#wsSearch').oninput=e=>{page.searchDraft=e.target.value};
 $('#wsSearchForm').onsubmit=e=>{e.preventDefault();WS.q=$('#wsSearch').value;WS.offset=0;return wsRefresh()};
 $('#wsHandoffState').onchange=e=>{WS.handoffState=e.target.value;WS.offset=0;return wsRefresh()};
 $('#wsPrev').onclick=()=>{WS.offset=Math.max(0,WS.offset-30);return wsRefresh()};$('#wsNext').onclick=()=>{WS.offset+=30;return wsRefresh()};
 $('#wsReload').onclick=()=>wsRefresh();return page;
}
async function wsSelect(page,key,focus=false){if(!wsLive(page))return;WS.selected=key;page.selected=key;page.selection++;const target=$('#wsDetail');await handoffsOpen(target,key,()=>wsLive(page)&&page.selected===key,focus,()=>wsLive(page)?wsRefresh():undefined);if(!wsLive(page))return;page.host.querySelectorAll('[data-ws-open]').forEach(b=>{b.setAttribute('aria-pressed',String(b.dataset.wsOpen===key))})}
async function vWorkspace(ticketKey=''){
 const scope=scopeQ();if(WS.lastScope!==scope){WS.offset=0;WS.lastScope=scope;WS.selected=''}
 const page=WS.page&&wsLive(WS.page)?WS.page:wsShell(),request=++WS.read;
 const notice=$('#wsQueueNotice');notice.textContent='正在读取真实任务和交接记录…';$('#wsReload').disabled=true;
 try{
  const data=await get('/api/workspace?project='+encodeURIComponent(scope)+'&view='+encodeURIComponent(WS.view||(S.meta.login?'mine':'team'))+'&q='+encodeURIComponent(WS.q)+'&stage='+encodeURIComponent(WS.stage)+'&handoff_state='+encodeURIComponent(WS.handoffState)+'&offset='+WS.offset);
  if(!wsLive(page)||request!==WS.read)return;
  if(data.total&&WS.offset>=data.total){WS.offset=Math.floor((data.total-1)/30)*30;return vWorkspace(ticketKey)}
  const active=document.activeElement,focusKey=active?.dataset?.wsView?'[data-ws-view="'+active.dataset.wsView+'"]':active?.dataset?.wsStage?'[data-ws-stage="'+active.dataset.wsStage+'"]':active?.dataset?.wsOpen?'[data-ws-open="'+active.dataset.wsOpen+'"]':'';
  page.data=data;$('#wsScope').textContent=(data.viewer||'团队')+' · '+(data.project==='*'?'全部项目':data.project);
  const labels={mine:'我负责的',incoming:'待我接手',review:'待我复核',team:'团队进行中',unassigned:'待分配'};
  $('#wsViews').innerHTML=Object.entries(labels).map(([key,label])=>`<button data-ws-view="${key}" class="${key===data.view?'on':''}" aria-pressed="${key===data.view}">${label}<span>${h(key==='incoming'?data.incoming_count:data.counts[key])}</span></button>`).join('');
  const counts=data.stage_counts||{};$('#wsStages').innerHTML=`<button data-ws-stage="all" aria-pressed="${WS.stage==='all'}">全部阶段</button>`+Object.entries(WS_STAGES).map(([key,label])=>`<button data-ws-stage="${key}" aria-pressed="${WS.stage===key}"><span>${label}</span><b>${counts[key]===undefined?'未知':h(counts[key])}</b></button>`).join('');
  $('#wsQueue').innerHTML=data.items.length?data.items.map(t=>`<article class="ws-flow-row"><div class="ws-row-meta"><span>${h(t.key)}</span><span>${h(t.stage_label||'未登记阶段')}</span>${stPill(t.status)}</div><button class="ws-select-task" data-ws-open="${h(t.key)}" aria-pressed="${t.key===page.selected}">${h(t.title)}</button><dl class="ws-row-owners"><dt>当前负责人</dt><dd>${h(t.assignee||'待分配')}</dd><dt>下一责任人</dt><dd>${h(t.next_actor||'未登记')}</dd></dl><div class="ws-row-meta"><span>${h(t.work?.label||'进展待读取')}</span><span>${h(wsHandoffWait(t.handoff,t.waiting_seconds))}</span></div>${wsMeetingLink(t)}${t.handoff?.block_reason?`<p class="ws-block-reason">${h(t.handoff.block_reason)}</p>`:''}<a class="ws-task-action" href="${h(wsActionHref(t,data.view==='review'))}">${h(t.action_label||'查看处理入口')} ${workIcon('next')}</a></article>`).join(''):`<div class="ws-empty"><h2>${WS.q?'没有匹配任务':'当前筛选没有任务'}</h2><p>可切换工作范围、交接阶段或搜索关键词；空队列不代表项目已经完成。</p><button id="wsClearFilters">清除筛选</button></div>`;
  $('#wsPageCount').textContent=data.total?`${data.offset+1}–${Math.min(data.offset+30,data.total)} / ${data.total} 项`:'0 项';$('#wsPrev').disabled=!data.offset;$('#wsNext').disabled=!data.has_more;
  page.host.querySelectorAll('[data-ws-view]').forEach(b=>b.onclick=()=>{WS.view=b.dataset.wsView;WS.offset=0;return wsRefresh()});page.host.querySelectorAll('[data-ws-stage]').forEach(b=>b.onclick=()=>{WS.stage=b.dataset.wsStage;WS.offset=0;return wsRefresh()});page.host.querySelectorAll('[data-ws-open]').forEach(b=>b.onclick=()=>wsSelect(page,b.dataset.wsOpen,true));
  page.host.querySelectorAll('[data-ws-meeting]').forEach(a=>a.onclick=()=>{setProj(a.dataset.wsProject);S.scope=a.dataset.wsProject;ls.set('tmh.scope',S.scope)});
  if($('#wsClearFilters'))$('#wsClearFilters').onclick=()=>{WS.q='';WS.stage='all';WS.handoffState='all';WS.offset=0;$('#wsSearch').value='';$('#wsHandoffState').value='all';return wsRefresh()};
  if(focusKey)page.host.querySelector(focusKey)?.focus();
  notice.textContent='按真实登记记录展示；队列刷新不会覆盖右侧未提交的交接草稿。';
  if(ticketKey&&page.selected!==ticketKey)await wsSelect(page,ticketKey);else if(!page.selected&&data.items.length)await wsSelect(page,data.items[0].key);
 }catch(error){if(wsLive(page)&&request===WS.read){notice.innerHTML=`<div class="ws-inline-error" role="alert">${h(error.message)} <button id="wsRetry">重试读取</button></div>`;$('#wsRetry').onclick=()=>vWorkspace(ticketKey)}}
 finally{if(wsLive(page)&&request===WS.read)$('#wsReload').disabled=false}
}
async function vProjects(key){
  const route=location.hash, request=++WS.read;
  if(key){const p=S.projects.find(p=>p.key===key);if(!p)throw apiErr('没有这个项目，请返回项目列表。');setProj(key);S.scope=key;ls.set('tmh.scope',key);paintSel();
    const d=await get('/api/workspace?project='+encodeURIComponent(key)+'&view=team');
    if(route!==location.hash||request!==WS.read||S.proj!==key)return;
    $('#main').innerHTML=`<div class="ws-head"><div><a class="sub" href="#/projects">项目 /</a><h1>${h(p.name)}</h1><p class="sub">${h(p.description||'连接项目、任务与团队经验。')}</p></div><div class="wk-toolbar">${p.workflow==='reference'?'':'<button onclick="newTicket()">新建任务</button>'}<a class="btn primary" href="#/handoff/${encodeURIComponent(key)}">项目讲解与交接</a></div></div>
    <div class="ws-columns"><section><div class="ws-panel ws-project-intro"><span class="ws-eyebrow">${h(key)} · ${p.workflow==='reference'?'参考知识项目':'开发与维护项目'}</span><h2>从当前进度继续</h2><p>${d.counts.team} 项任务进行中。打开任务查看现象、下一步和相关依据，或进入团队协作分配负责人。</p><div class="wk-toolbar"><a class="btn" href="#/team/team" onclick="S.scope=S.proj;ls.set('tmh.scope',S.scope)">分配与复核</a><a class="btn" href="#/meetings">会议与行动</a><a class="btn" href="#/reform">重构计划</a><a class="btn" href="#/versions">版本记录</a></div></div><div class="hdr"><h2 class="grow">进行中的任务</h2><a href="#/tickets" onclick="S.scope=S.proj;ls.set('tmh.scope',S.scope)">全部任务</a></div><div class="ws-list">${d.items.length?d.items.map(t=>wsTaskRow(t)).join(''):'<div class="ws-empty"><h2>项目已连接</h2><p>创建任务，或先查看项目讲解了解代码和业务。</p></div>'}</div>${d.has_more?'<p class="sub">这里展示最近 30 项。<a href="#/tickets">打开全部任务</a></p>':''}</section>
    <aside class="ws-aside"><section class="ws-panel"><h2>理解这个项目</h2><div class="ws-quicklinks"><a href="#/handoff/${encodeURIComponent(key)}">项目讲解与交接 ${workIcon('next')}</a><a href="#/atlas">业务与代码图谱 ${workIcon('next')}</a><a href="#/kb">项目知识页 ${workIcon('next')}</a><a id="projectLearningLink" href="#/memory/learning">分类与评审 ${workIcon('next')}</a><a href="#/memory/clusters" onclick="S.scope=S.proj;ls.set('tmh.scope',S.scope)">同类问题与经验 ${workIcon('next')}</a><a href="#/library">参考项目与引用 ${workIcon('next')}</a></div></section><section class="ws-panel"><h2>项目工具</h2><div class="ws-quicklinks"><a href="#/runs">智能体运行 ${workIcon('next')}</a><a href="#/overview">监控总览 ${workIcon('next')}</a><a href="#/int">外部系统 ${workIcon('next')}</a><a href="#/settings">项目配置 ${workIcon('next')}</a></div></section></aside></div>`;
    $('#projectLearningLink').onclick=()=>{if(route!==location.hash||S.proj!==key||!S.projects.some(item=>item.key===key))return false;S.scope=key;ls.set('tmh.scope',key)};return}
  const data=await get('/api/workspace?project=*&view=team');
  if(route!==location.hash||request!==WS.read)return;
  $('#main').innerHTML=`<div class="ws-head"><div><span class="ws-eyebrow">团队项目</span><h1>项目</h1><p class="sub">进入项目接着做，或先读一份有来源的交接说明。</p></div><button class="primary" onclick="newProject()">连接项目</button></div><label class="ws-project-search">查找项目<input type="search" id="wsProjectSearch" placeholder="项目名称、编号或描述"></label><div class="ws-list" id="wsProjects"></div>`;
  const draw=q=>{const ps=data.projects.filter(p=>(p.key+' '+p.name+' '+p.description).toLowerCase().includes(q.toLowerCase()));$('#wsProjects').innerHTML=ps.length?ps.map(p=>`<article class="ws-row"><span class="ws-project-avatar">${h(p.key.slice(0,2))}</span><div class="grow"><a class="ws-row-title" href="#/projects/${encodeURIComponent(p.key)}">${h(p.name)}</a><div class="ws-row-meta">${h(p.key)} · ${h(p.description||'尚未填写项目说明')}</div></div><span class="sub">${p.open} 项进行中</span><a class="btn" href="#/handoff/${encodeURIComponent(p.key)}">交接说明</a><a class="btn ghost" href="#/projects/${encodeURIComponent(p.key)}">进入项目 ${workIcon('next')}</a></article>`).join(''):'<div class="ws-empty"><h2>没有匹配的项目</h2><p>连接现有代码仓库后，就可以创建任务并积累团队知识。</p><button onclick="newProject()">连接项目</button></div>'};draw('');$('#wsProjectSearch').oninput=e=>draw(e.target.value);
}
function ticketWorkspaceCard(d){const a=d.team_assignment||{};return `<section class="card ws-ticket-team"><h2>协作与知识</h2><dl><dt>负责人</dt><dd>${h(a.assignee||d.ticket.assignee||'待分配')}</dd><dt>复核人</dt><dd>${h(a.reviewer||'待分配')}</dd></dl><div class="ws-quicklinks"><a href="#/workspace/${encodeURIComponent(d.ticket.key)}">任务交接 / 下一责任人 ${workIcon('next')}</a><a href="#/team/ticket/${encodeURIComponent(d.ticket.key)}">分配任务 / 提交与复核代码 ${workIcon('next')}</a><a href="#/handoff/${encodeURIComponent(d.project.key)}">项目讲解与交接 ${workIcon('next')}</a><a href="#/memory/clusters" onclick="S.scope=S.proj;ls.set('tmh.scope',S.scope)">同类问题与解决经验 ${workIcon('next')}</a></div></section>`}
"""
